cases.bad:
.imageThumb { height: 120px; }
.imageImg { height: 120px; max-width: 200px; }
.imageAddButton { width: 80px; height: 120px; }
.mediaThumb { width: 28px; height: 28px; }
.removeButton { width: 20px; height: 20px; font-size: 16px; }

cases.good:
.imageThumb { height: calc(var(--space-5) * 6); }
.imageImg { height: calc(var(--space-5) * 6); max-width: calc(var(--space-5) * 10); }
.imageAddButton { width: calc(var(--space-5) * 4); height: calc(var(--space-5) * 6); }
.mediaThumb { width: calc(var(--space-5) + var(--space-2)); height: calc(var(--space-5) + var(--space-2)); }
.removeButton { width: var(--space-5); height: var(--space-5); font-size: var(--space-4); }
